@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root {
  color-scheme: light;
  --paper: #f4f3ed;
  --ink: #20231f;
  --muted: #898b82;
  --line: #e8e7df;
  --coral: #ff755b;
  --coral-dark: #ef654d;
  --mint: #58c6a9;
  --green: #cbf27e;
  --panel: #fffefa;
  --shadow: 0 22px 65px rgba(45, 48, 36, .07);
  font-family: 'DM Sans', sans-serif;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  color: var(--ink);
  background-color: var(--paper);
  background-image: radial-gradient(ellipse at 87% 14%, rgba(203,242,126,.19), transparent 28%), radial-gradient(ellipse at 5% 88%, rgba(255,117,91,.08), transparent 24%);
  -webkit-font-smoothing: antialiased;
}
button { font: inherit; }
.page-shell { width: min(1120px, calc(100% - 72px)); margin: 0 auto; }
.topbar { height: 91px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(32,35,31,.1); }
.brand { display: inline-flex; gap: 11px; align-items: center; color: var(--ink); text-decoration: none; font: 700 16px 'Space Grotesk', sans-serif; letter-spacing: -.7px; }
.brand-dot { color: var(--coral); }
.brand-mark { width: 25px; height: 25px; background: var(--ink); border-radius: 8px; padding: 6px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 3px; transform: rotate(-7deg); }
.brand-mark i { background: var(--green); border-radius: 2px; }
.brand-mark i:nth-child(2), .brand-mark i:nth-child(3) { background: var(--coral); }
.top-note { display: flex; align-items: center; gap: 8px; font-size: 9px; font-weight: 700; letter-spacing: 1.65px; color: #777a71; }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: #75c9a0; box-shadow: 0 0 0 3px rgba(117,201,160,.17); }
.text-button { border: 0; background: transparent; padding: 10px 0 10px 10px; color: #777a71; display: flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 600; cursor: pointer; transition: color .2s; }
.text-button:hover { color: var(--ink); }
.text-button svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }

.game-layout { min-height: 650px; display: grid; grid-template-columns: .84fr 1.16fr; align-items: center; gap: clamp(42px, 8vw, 112px); padding: 61px 0 59px; }
.intro-panel { max-width: 350px; }
.eyebrow { margin: 0 0 22px; color: #898b82; font-size: 9px; font-weight: 700; letter-spacing: 1.75px; display: flex; align-items: center; gap: 9px; }
.eyebrow-line { display: inline-block; width: 21px; height: 1px; background: var(--coral); }
h1 { margin: 0; font: 600 clamp(62px, 7.3vw, 88px)/.91 'Space Grotesk', sans-serif; letter-spacing: -7.5px; }
h1 span { color: var(--coral); }
.intro-copy { margin: 20px 0 29px; font-size: 14px; line-height: 1.7; color: #777970; }
.mode-picker { display: inline-flex; gap: 3px; padding: 4px; background: #eae9e1; border-radius: 9px; margin-bottom: 27px; }
.mode-button { height: 34px; display: inline-flex; gap: 7px; align-items: center; padding: 0 11px; border: 0; border-radius: 6px; background: transparent; color: #777970; font-size: 10px; font-weight: 600; cursor: pointer; transition: all .2s; }
.mode-button svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.4; stroke-linecap: round; stroke-linejoin: round; }
.mode-button.active { color: var(--ink); background: var(--panel); box-shadow: 0 2px 6px rgba(28,30,22,.08); }
.mode-button:focus-visible, .text-button:focus-visible, .next-button:focus-visible, .cell:focus-visible { outline: 3px solid rgba(255,117,91,.5); outline-offset: 3px; }
.scoreboard { padding: 17px 18px 10px; width: 100%; max-width: 313px; background: rgba(255,254,250,.66); border: 1px solid rgba(32,35,31,.07); border-radius: 12px; }
.score-heading { display: flex; justify-content: space-between; align-items: center; padding-bottom: 10px; color: #999a91; font-size: 8px; letter-spacing: 1.2px; font-weight: 700; }
.round-label { color: #b0b0a7; }
.score-row { min-height: 41px; display: flex; align-items: center; justify-content: space-between; border-top: 1px solid rgba(32,35,31,.07); }
.score-player { display: flex; align-items: center; gap: 9px; min-width: 0; }
.score-symbol { width: 18px; font: 500 24px/1 'Space Grotesk',sans-serif; color: var(--coral); text-align: center; }
.o-player .score-symbol { color: var(--mint); font-size: 19px; }
.score-name { color: #777970; font-size: 11px; font-weight: 500; }
.score-value { font: 600 16px 'Space Grotesk', sans-serif; }
.draws-row .score-name, .draws-row .score-value { color: #9c9d94; }
.draw-icon { width: 18px; color: #aaa99f; font-size: 13px; font-weight: 700; text-align: center; }
.tiny-note { margin: 19px 0 0; color: #999a91; font-size: 10px; }
.tiny-note span { color: var(--coral); margin-right: 5px; }

.play-panel { background: var(--panel); border: 1px solid rgba(32,35,31,.055); box-shadow: var(--shadow); border-radius: 17px; padding: 25px 28px 20px; position: relative; overflow: hidden; }
.play-panel::before { content: ''; pointer-events: none; position: absolute; top: -99px; right: -66px; width: 172px; height: 172px; border-radius: 50%; background: rgba(203,242,126,.12); }
.play-topline { min-height: 32px; display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 17px; position: relative; }
.game-label { display: flex; align-items: center; gap: 6px; font-size: 8px; font-weight: 700; letter-spacing: 1.15px; color: #73756d; white-space: nowrap; }
.game-label-icon { color: var(--coral); font-size: 13px; margin-right: 2px; }
.label-separator { color: #c4c3b9; margin: 0 1px; }
.turn-pill { height: 29px; max-width: 52%; padding: 0 10px 0 7px; display: inline-flex; align-items: center; gap: 5px; background: #f4f3ed; border-radius: 30px; color: #74766d; font-size: 9px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: background .2s; }
.turn-mark { font: 500 18px/1 'Space Grotesk', sans-serif; }
.x-mark { color: var(--coral); }
.o-mark { color: var(--mint); }
.turn-pill.is-won { background: #eff8df; color: #576c35; }
.turn-pill.is-draw { background: #f1f0eb; }
.board-wrap { background: #242722; border-radius: 11px; padding: 8px; box-shadow: 0 5px 12px rgba(26,28,23,.11); }
.board { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; aspect-ratio: 1 / 1; }
.cell { position: relative; min-width: 0; padding: 0; border: 0; border-radius: 6px; background: #fffefa; color: var(--ink); display: grid; place-items: center; cursor: pointer; transition: background .17s, transform .17s; -webkit-tap-highlight-color: transparent; }
.cell:not(:disabled):hover { background: #f4f5ec; transform: scale(.975); }
.cell:disabled { cursor: default; }
.cell::before { content: ''; width: 39%; aspect-ratio: 1; }
.cell.x::before { background: var(--coral); clip-path: polygon(20% 5%, 50% 35%, 80% 5%, 95% 20%, 65% 50%, 95% 80%, 80% 95%, 50% 65%, 20% 95%, 5% 80%, 35% 50%, 5% 20%); animation: mark-in .22s cubic-bezier(.18,.8,.25,1.3) both; }
.cell.o::before { border: clamp(5px, .7vw, 8px) solid var(--mint); border-radius: 50%; animation: mark-in .22s cubic-bezier(.18,.8,.25,1.3) both; }
.cell.winner { background: #f0f8e3; }
.cell.winner.x::before { background: var(--coral-dark); }
.cell.winner.o::before { border-color: #3ab390; }
.cell:disabled:not(.x):not(.o) { opacity: 1; }
@keyframes mark-in { from { transform: scale(.35); opacity: .25; } to { transform: scale(1); opacity: 1; } }
.play-bottomline { min-height: 47px; display: flex; align-items: end; justify-content: space-between; gap: 10px; }
.game-hint { margin: 0 0 4px; font-size: 10px; color: #96978e; }
.hint-sparkle { color: #c1d980; margin-right: 4px; }
.next-button { border: 0; border-radius: 7px; padding: 0 12px; height: 33px; display: inline-flex; gap: 8px; align-items: center; color: #fffefa; background: var(--ink); font-size: 10px; font-weight: 600; cursor: pointer; transition: background .18s, transform .18s; white-space: nowrap; }
.next-button:hover { background: #3a3e37; transform: translateY(-1px); }
.next-button svg { width: 15px; height: 15px; fill: none; stroke: var(--green); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.footer { min-height: 63px; border-top: 1px solid rgba(32,35,31,.1); display: flex; align-items: center; justify-content: space-between; color: #a0a097; font-size: 8px; font-weight: 700; letter-spacing: 1.4px; }
.footer b { margin-left: 5px; color: var(--coral); font-size: 11px; }

@media (min-width: 1200px) { .game-layout { min-height: 692px; } }
@media (max-width: 820px) {
  .page-shell { width: min(620px, calc(100% - 40px)); }
  .game-layout { min-height: initial; grid-template-columns: 1fr; gap: 34px; padding: 43px 0 48px; }
  .intro-panel { max-width: none; display: grid; grid-template-columns: 1fr auto; align-items: end; }
  .eyebrow { grid-column: 1 / -1; margin-bottom: 16px; }
  h1 { font-size: clamp(59px, 11vw, 80px); }
  .intro-copy { grid-column: 1; grid-row: 3; margin: 12px 0 0; }
  .mode-picker { grid-column: 2; grid-row: 2 / span 2; margin: 0 0 2px 12px; }
  .scoreboard { grid-column: 1 / -1; max-width: none; margin-top: 22px; display: grid; grid-template-columns: repeat(3, 1fr); padding: 12px 15px 7px; }
  .score-heading { grid-column: 1 / -1; }
  .score-row { padding: 0 8px; border-top: 1px solid rgba(32,35,31,.07); }
  .score-row + .score-row { border-left: 1px solid rgba(32,35,31,.07); }
  .tiny-note { display: none; }
  .play-panel { padding: 23px 24px 18px; }
  .play-bottomline { min-height: 44px; }
  .footer { min-height: 53px; }
}
@media (max-width: 500px) {
  .page-shell { width: calc(100% - 32px); }
  .topbar { height: 69px; }
  .top-note { display: none; }
  .brand { font-size: 15px; }
  .text-button { font-size: 10px; }
  .game-layout { gap: 26px; padding: 34px 0 35px; }
  .eyebrow { font-size: 8px; margin-bottom: 13px; }
  h1 { font-size: clamp(54px, 16vw, 73px); letter-spacing: -5.8px; }
  .intro-copy { font-size: 12px; line-height: 1.55; }
  .mode-picker { gap: 1px; padding: 3px; margin-left: 4px; }
  .mode-button { height: 32px; padding: 0 8px; gap: 5px; font-size: 9px; }
  .mode-button svg { width: 13px; height: 13px; }
  .scoreboard { margin-top: 20px; padding: 10px 9px 5px; }
  .score-row { padding: 0 4px; min-height: 38px; gap: 3px; }
  .score-player { gap: 4px; }
  .score-name { font-size: 9px; }
  .score-symbol { width: 15px; font-size: 20px; }
  .o-player .score-symbol { font-size: 16px; }
  .score-value { font-size: 14px; }
  .play-panel { padding: 17px 14px 14px; border-radius: 13px; }
  .play-topline { margin-bottom: 13px; }
  .game-label { font-size: 7px; gap: 4px; letter-spacing: .9px; }
  .turn-pill { padding: 0 8px 0 6px; font-size: 8px; }
  .board-wrap { padding: 6px; border-radius: 9px; }
  .board { gap: 4px; }
  .cell { border-radius: 5px; }
  .game-hint { max-width: 58%; font-size: 9px; line-height: 1.4; }
  .next-button { padding: 0 9px; font-size: 9px; }
  .footer { font-size: 7px; letter-spacing: .9px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .01ms !important; } }

(() => {
  const cells = [...document.querySelectorAll('.cell')];
  const turnMark = document.querySelector('.turn-mark');
  const turnLabel = document.getElementById('turn-label');
  const turnPill = document.getElementById('turn-pill');
  const hint = document.getElementById('game-hint');
  const modeButtons = [...document.querySelectorAll('.mode-button')];
  const winningLines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  const storageKey = 'little-games-tic-tac-toe-scores';

  let board = Array(9).fill('');
  let current = 'X';
  let gameOver = false;
  let thinking = false;
  let mode = 'friends';
  let round = 1;
  let scores = { X: 0, O: 0, draws: 0 };

  try {
    const stored = JSON.parse(localStorage.getItem(storageKey));
    if (stored && ['X', 'O', 'draws'].every(key => Number.isInteger(stored[key]) && stored[key] >= 0)) scores = stored;
  } catch (_) { /* Start with a clean score if storage is unavailable. */ }

  function playerName(mark) {
    return mark === 'X' ? 'Player 1' : mode === 'computer' ? 'Computer' : 'Player 2';
  }

  function saveScores() {
    try { localStorage.setItem(storageKey, JSON.stringify(scores)); } catch (_) { /* The game still works without storage. */ }
  }

  function updateScoreboard() {
    document.getElementById('x-score').textContent = scores.X;
    document.getElementById('o-score').textContent = scores.O;
    document.getElementById('draw-score').textContent = scores.draws;
    document.getElementById('x-name').textContent = 'Player 1';
    document.getElementById('o-name').textContent = mode === 'computer' ? 'Computer' : 'Player 2';
    const roundText = String(round).padStart(2, '0');
    document.getElementById('round-label').textContent = `ROUND ${roundText}`;
    document.getElementById('panel-round').textContent = roundText;
  }

  function setTurn(mark) {
    current = mark;
    turnMark.textContent = mark === 'X' ? '×' : '○';
    turnMark.className = `turn-mark ${mark === 'X' ? 'x-mark' : 'o-mark'}`;
    turnPill.classList.remove('is-won', 'is-draw');
    turnLabel.textContent = mode === 'computer' && mark === 'O' ? 'Computer is thinking…' : `${playerName(mark)}'s turn`;
    hint.innerHTML = '<span class="hint-sparkle">✦</span> Three of your marks. That’s the whole plan.';
    render();
  }

  function render() {
    cells.forEach((cell, index) => {
      const mark = board[index];
      cell.classList.toggle('x', mark === 'X');
      cell.classList.toggle('o', mark === 'O');
      cell.disabled = Boolean(mark) || gameOver || thinking;
      const row = Math.floor(index / 3) + 1;
      const column = index % 3 + 1;
      cell.setAttribute('aria-label', `Row ${row}, column ${column}, ${mark ? mark.toUpperCase() : 'empty'}`);
    });
  }

  function getWinner(position) {
    for (const line of winningLines) {
      const [a, b, c] = line;
      if (position[a] && position[a] === position[b] && position[a] === position[c]) return { mark: position[a], line };
    }
    return null;
  }

  function play(index) {
    if (gameOver || thinking || board[index] || (mode === 'computer' && current === 'O')) return;
    board[index] = current;
    const result = getWinner(board);
    if (result) {
      gameOver = true;
      result.line.forEach(cellIndex => cells[cellIndex].classList.add('winner'));
      scores[result.mark]++;
      saveScores();
      updateScoreboard();
      turnMark.textContent = result.mark === 'X' ? '×' : '○';
      turnMark.className = `turn-mark ${result.mark === 'X' ? 'x-mark' : 'o-mark'}`;
      turnLabel.textContent = `${playerName(result.mark)} wins!`;
      turnPill.classList.add('is-won');
      hint.innerHTML = `<span class="hint-sparkle">✦</span> Three in a row. Nicely played!`;
      render();
      return;
    }
    if (board.every(Boolean)) {
      gameOver = true;
      scores.draws++;
      saveScores();
      updateScoreboard();
      turnMark.textContent = '=';
      turnMark.className = 'turn-mark';
      turnLabel.textContent = 'It’s a draw!';
      turnPill.classList.add('is-draw');
      hint.innerHTML = '<span class="hint-sparkle">✦</span> Too evenly matched. One more round?';
      render();
      return;
    }

    setTurn(current === 'X' ? 'O' : 'X');
    if (mode === 'computer' && current === 'O') {
      thinking = true;
      render();
      window.setTimeout(() => {
        const move = bestComputerMove();
        thinking = false;
        if (move !== -1) play(move);
      }, 420);
    }
  }

  // Minimax keeps the computer challenging but beatable only by a draw.
  function minimax(position, mark, depth) {
    const winner = getWinner(position);
    if (winner?.mark === 'O') return 10 - depth;
    if (winner?.mark === 'X') return depth - 10;
    if (position.every(Boolean)) return 0;

    const moves = [];
    position.forEach((value, index) => {
      if (value) return;
      position[index] = mark;
      moves.push({ index, score: minimax(position, mark === 'O' ? 'X' : 'O', depth + 1) });
      position[index] = '';
    });
    return mark === 'O' ? Math.max(...moves.map(move => move.score)) : Math.min(...moves.map(move => move.score));
  }

  function bestComputerMove() {
    let bestScore = -Infinity;
    let bestMove = -1;
    board.forEach((value, index) => {
      if (value) return;
      board[index] = 'O';
      const score = minimax(board, 'X', 0);
      board[index] = '';
      if (score > bestScore) { bestScore = score; bestMove = index; }
    });
    return bestMove;
  }

  function newRound(increment = true) {
    if (increment) round++;
    board = Array(9).fill('');
    gameOver = false;
    thinking = false;
    cells.forEach(cell => cell.classList.remove('winner'));
    updateScoreboard();
    setTurn('X');
  }

  cells.forEach((cell, index) => cell.addEventListener('click', () => play(index)));
  document.getElementById('new-game').addEventListener('click', () => newRound());

  modeButtons.forEach(button => button.addEventListener('click', () => {
    if (button.dataset.mode === mode) return;
    mode = button.dataset.mode;
    modeButtons.forEach(item => {
      const active = item === button;
      item.classList.toggle('active', active);
      item.setAttribute('aria-pressed', String(active));
    });
    newRound();
  }));

  document.getElementById('reset-scores').addEventListener('click', () => {
    scores = { X: 0, O: 0, draws: 0 };
    round = 1;
    saveScores();
    updateScoreboard();
  });

  updateScoreboard();
  setTurn('X');
})();

